create extension pg_trgm;
create table clientes (id serial primary key, nombre text not null);
-- ... 300.000 nombres inventados, semilla fija ...

explain (analyze, costs off, timing off)
select id, nombre from clientes where nombre ilike '%espiga 2999%';

create index clientes_trgm on clientes using gin (nombre gin_trgm_ops);

explain (analyze, costs off, timing off)
select id, nombre from clientes where nombre ilike '%espiga 2999%';

select nombre, round(similarity(nombre, 'Panifcadora La Espga')::numeric, 2) as parecido
from clientes where nombre % 'Panifcadora La Espga' order by parecido desc, id limit 3;

