create table eventos (
  id     bigint generated always as identity primary key,
  bulto  integer     not null,
  cuando timestamptz not null,
  datos  jsonb       not null
);
-- ... 300.000 filas generadas con jsonb_build_object y semilla fija ...

select datos->>'tipo' as tipo, count(*) from eventos group by 1 order by 2 desc;
select count(*) from eventos where datos @> '{"tipo":"incidente","sensor":{"golpe":true}}';

create index eventos_gin_pp on eventos using gin (datos jsonb_path_ops);

